// BGPVIPConfig carries the BGP peering configuration for BGP-based VIP
// management (enhancement openshift/enhancements#1982). It is a singleton
// named "cluster", generated by the installer from
// platform.baremetal.bgpVIPConfig in the install-config, and may be edited
// day-2 to reconfigure peering. The configuration is rendered into
// node-level BGP configuration by its consumers, the
// machine-config-operator and the cluster-network-operator, which report
// their progress in status.
//
// Compatibility level 4: No compatibility is provided, the API can change at any point for any reason. These capabilities should not be used by applications needing long term support.
type BGPVIPConfig struct {
	metav1.TypeMeta `json:",inline"`

	// metadata is the standard object's metadata.
	// More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#metadata
	// +required
	metav1.ObjectMeta `json:"metadata,omitempty"`

	// spec is the desired BGP VIP peering configuration.
	// +required
	Spec BGPVIPConfigSpec `json:"spec,omitempty,omitzero"`

	// status reports the consumers' progress applying the configuration.
	// +optional
	Status BGPVIPConfigStatus `json:"status,omitempty,omitzero"`
}

// BGPVIPConfigSpec describes the BGP peering used to advertise the API and
// Ingress VIPs.
type BGPVIPConfigSpec struct {
	// localASN is the BGP autonomous system number (ASN) the cluster's BGP
	// speakers present to the configured peers. Use the ASN your network
	// administrator assigned to the cluster - the peer routers must expect
	// it or no session establishes; private-range ASNs (e.g. 64512-65534)
	// are typical for datacenter fabrics. Must be at least 1 and must not
	// exceed 4294967295.
	// +kubebuilder:validation:Minimum=1
	// +kubebuilder:validation:Maximum=4294967295
	// +required
	LocalASN int64 `json:"localASN,omitempty"`

	// defaultPeers are the BGP peers every node establishes sessions with,
	// unless the node is named in hostOverrides. Must have at least 1 entry
	// and must not exceed 16 entries, unique by peerAddress.
	// +listType=map
	// +listMapKey=peerAddress
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	// +required
	DefaultPeers []BGPVIPPeer `json:"defaultPeers,omitempty"`

	// communities are BGP community strings attached to the VIP
	// advertisements: "n:n" classic communities (RFC 1997) where each
	// segment is a 16-bit value of at least 0 and not exceeding 65535, or
	// "n:n:n" large communities (RFC 8092) where each segment is a 32-bit
	// value of at least 0 and not exceeding 4294967295. When omitted, no
	// communities are attached. Entries are unique; when set, must have at
	// least 1 entry and must not exceed 8 entries.
	// +listType=set
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=8
	// +optional
	Communities []BGPCommunity `json:"communities,omitempty"`

	// hostOverrides replaces (does not merge with) defaultPeers for the
	// named nodes. Only the per-node peer file rendered by the
	// machine-config-operator consumes overrides; the cluster-wide session
	// configuration rendered by the cluster-network-operator uses
	// defaultPeers. When omitted, all nodes use defaultPeers; when set, must
	// have at least 1 entry and must not exceed 256 entries, unique by
	// hostname.
	// +listType=map
	// +listMapKey=hostname
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=256
	// +optional
	HostOverrides []BGPVIPHostPeers `json:"hostOverrides,omitempty"`
}

// BGPCommunity is a BGP community string: colon-separated decimal
// numbers without leading zeros - "n:n" for a classic community
// (RFC 1997, 16-bit segments of at least 0 and not exceeding 65535) or
// "n:n:n" for a large community (RFC 8092, 32-bit segments of at least 0
// and not exceeding 4294967295). Must be at least 3 characters in length
// and must not exceed 32 characters.
// +kubebuilder:validation:MinLength=3
// +kubebuilder:validation:MaxLength=32
// +kubebuilder:validation:XValidation:rule="self.matches('^(0|[1-9][0-9]*)(:(0|[1-9][0-9]*)){1,2}$')",message="must be a classic (n:n) or large (n:n:n) BGP community: colon-separated decimal numbers without leading zeros"
// +kubebuilder:validation:XValidation:rule="!self.matches('^(0|[1-9][0-9]*)(:(0|[1-9][0-9]*)){1,2}$') || (self.split(':').size() == 2 ? self.split(':').all(s, s.size() <= 5 && int(s) <= 65535) : self.split(':').all(s, s.size() <= 10 && int(s) <= 4294967295))",message="classic community (n:n) segments must be between 0 and 65535; large community (n:n:n) segments must be between 0 and 4294967295"
type BGPCommunity string

// BGPVIPHostPeers is a per-node replacement peer list.
type BGPVIPHostPeers struct {
	// hostname of the node this override applies to, as a non-empty RFC
	// 1123 subdomain of at most 253 characters with dot-separated labels of
	// at most 63 characters each. It is compared verbatim against
	// the hostname the node resolves for itself (as rendered into the
	// per-node peer file), so a short name and its fully qualified form are
	// distinct entries and only the exact match applies.
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=253
	// +kubebuilder:validation:XValidation:rule="self.matches('^[a-z0-9]([-a-z0-9]{0,61}[a-z0-9])?(\\\\.[a-z0-9]([-a-z0-9]{0,61}[a-z0-9])?)*$')",message="hostname must be an RFC 1123 subdomain with labels of at most 63 characters"
	// +required
	Hostname string `json:"hostname,omitempty"`

	// peers replaces defaultPeers for this node. Must have at least 1 entry
	// and must not exceed 16 entries, unique by peerAddress.
	// +listType=map
	// +listMapKey=peerAddress
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	// +required
	Peers []BGPVIPPeer `json:"peers,omitempty"`
}

// FailureDetectionMode describes what detects a failed BGP peer.
// +kubebuilder:validation:Enum:=BFD;HoldTimer
type FailureDetectionMode string

const (
	// FailureDetectionBFD backs the session with a BFD session for fast
	// failure detection.
	FailureDetectionBFD FailureDetectionMode = "BFD"
	// FailureDetectionHoldTimer relies on the BGP hold timer alone.
	FailureDetectionHoldTimer FailureDetectionMode = "HoldTimer"
)

// PeerReachabilityMode describes how the BGP peer is reached.
// +kubebuilder:validation:Enum:=DirectlyConnected;MultiHop
type PeerReachabilityMode string

const (
	// PeerReachabilityDirectlyConnected requires the peer to be on a
	// directly connected network.
	PeerReachabilityDirectlyConnected PeerReachabilityMode = "DirectlyConnected"
	// PeerReachabilityMultiHop allows the session to cross multiple
	// router hops.
	PeerReachabilityMultiHop PeerReachabilityMode = "MultiHop"
)

// BGPVIPPasswordSecret references a Secret in the openshift-config
// namespace by name.
type BGPVIPPasswordSecret struct {
	// name is the metadata.name of the referenced Secret in the
	// openshift-config namespace. Must be a non-empty RFC 1123 subdomain of
	// at most 253 characters, matching what Kubernetes accepts as a Secret
	// name.
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=253
	// +kubebuilder:validation:XValidation:rule="self.matches('^[a-z0-9]([-a-z0-9]*[a-z0-9])?(\\\\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*$')",message="name must be a lowercase RFC 1123 subdomain"
	// +required
	Name string `json:"name,omitempty"`
}

// BGPVIPPeer describes one BGP peer.
// +kubebuilder:validation:XValidation:rule="!(has(self.holdTimeSeconds) && has(self.keepaliveTimeSeconds)) || self.holdTimeSeconds >= 3 * self.keepaliveTimeSeconds",message="holdTimeSeconds must be at least 3 times keepaliveTimeSeconds"
type BGPVIPPeer struct {
	// peerAddress is the IP address of the BGP peer (IPv4 or IPv6) in
	// canonical form (lowercase, no leading zeros, IPv6 zero-compressed);
	// must be at least 2 characters in length and must not exceed 45
	// characters. The session's address family follows the address family
	// of this value. Canonical form is required so that two
	// spellings of one address cannot form duplicate peers.
	// +kubebuilder:validation:MinLength=2
	// +kubebuilder:validation:MaxLength=45
	// +kubebuilder:validation:XValidation:rule="isIP(self) && ip.isCanonical(self)",message="peerAddress must be a valid IP address in canonical form"
	// +required
	PeerAddress string `json:"peerAddress,omitempty"`

	// peerASN is the autonomous system number of the peer. Must be at
	// least 1 and must not exceed 4294967295.
	// +kubebuilder:validation:Minimum=1
	// +kubebuilder:validation:Maximum=4294967295
	// +required
	PeerASN int64 `json:"peerASN,omitempty"`

	// passwordSecret references the Secret carrying the TCP MD5 password
	// (RFC 2385) for the session. The Secret must be of type
	// kubernetes.io/basic-auth, live in the openshift-config namespace, and
	// carry the password in its "password" key (at most 80 bytes, the
	// kernel's TCP MD5 limit). The Secret type, key, and size requirements
	// are not validated by the API server; the consumers validate them when
	// resolving the reference and must never surface the Secret contents in
	// status, events, or logs. Passwords are never stored in this API. When
	// omitted, the session is unauthenticated.
	// +optional
	PasswordSecret BGPVIPPasswordSecret `json:"passwordSecret,omitempty,omitzero"`

	// port is the TCP port of the BGP session; must be at least 1 and must
	// not exceed 65535. When omitted, port 179 is used.
	// +kubebuilder:validation:Minimum=1
	// +kubebuilder:validation:Maximum=65535
	// +optional
	Port int32 `json:"port,omitempty"`

	// failureDetection determines how a failed peer is detected. When set
	// to "BFD", a BFD session is established with the peer and BGP reacts
	// to BFD failure detection. When set to "HoldTimer", failure detection
	// relies on the BGP hold timer alone. When omitted, failure detection
	// relies on the BGP hold timer.
	// +optional
	FailureDetection FailureDetectionMode `json:"failureDetection,omitempty"`

	// peerReachability describes how the peer is reached. When set to
	// "MultiHop", the session may be established with a peer several
	// router hops away. When set to "DirectlyConnected", the peer must be
	// on a directly connected network. When omitted, the peer must be
	// directly connected.
	// +optional
	PeerReachability PeerReachabilityMode `json:"peerReachability,omitempty"`

	// holdTimeSeconds is the BGP hold time in seconds; must be at least 3
	// (the RFC 4271 minimum for a non-zero hold time) and must not exceed
	// 65535. When omitted, no hold time is configured and the FRR default
	// (180 seconds) applies.
	// When both holdTimeSeconds and keepaliveTimeSeconds are set,
	// holdTimeSeconds must be at least 3 times keepaliveTimeSeconds.
	// +kubebuilder:validation:Minimum=3
	// +kubebuilder:validation:Maximum=65535
	// +optional
	HoldTimeSeconds int32 `json:"holdTimeSeconds,omitempty"`

	// keepaliveTimeSeconds is the BGP keepalive interval in seconds; must
	// be at least 1 and must not exceed 65535. When omitted, no keepalive
	// interval is configured and the FRR default (60 seconds) applies. When both
	// holdTimeSeconds and keepaliveTimeSeconds are set, holdTimeSeconds
	// must be at least 3 times keepaliveTimeSeconds.
	// +kubebuilder:validation:Minimum=1
	// +kubebuilder:validation:Maximum=65535
	// +optional
	KeepaliveTimeSeconds int32 `json:"keepaliveTimeSeconds,omitempty"`
}

// BGPVIPConfigStatus reports the consumers' progress applying the spec.
// +kubebuilder:validation:MinProperties=1
type BGPVIPConfigStatus struct {
	// conditions reports the state of processing the configuration; when
	// set, must have at least 1 entry and must not exceed 8 entries. Known
	// condition types are "Rendered" (the machine-config-operator has
	// rendered the per-node peer configuration) and "SessionsConfigured"
	// (the cluster-network-operator has rendered the FRR session
	// configuration for application). SessionsConfigured does not assert
	// that the generated FRRConfiguration was accepted by the frr-k8s
	// admission webhook or applied on the nodes. Each condition's
	// observedGeneration reports the generation of the spec most recently
	// processed by the operator that writes it.
	// +listType=map
	// +listMapKey=type
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=8
	// +optional
	Conditions []metav1.Condition `json:"conditions,omitempty"`
}

const (
	// BGPVIPConfigRendered is set by the machine-config-operator when the
	// per-node peer configuration reflecting the current spec generation
	// has been rendered.
	BGPVIPConfigRendered = "Rendered"
	// BGPVIPConfigSessionsConfigured is set by the cluster-network-operator
	// when the FRR session configuration reflecting the current spec has
	// been rendered for application. It does not assert admission-webhook
	// acceptance or on-node application of the generated FRRConfiguration.
	BGPVIPConfigSessionsConfigured = "SessionsConfigured"
)

// +k8s:deepcopy-gen:interfaces=k8s.io/apimachinery/pkg/runtime.Object
